def icon(n):return icons[n]
def panel(title,sub,body,extra=''):return f'<div class="panel"><div class="panelhead"><div><h2>{title}</h2><p>{sub}</p></div>{extra}</div>{body}</div>'
def chartblock():return '<div class="legend"><span><i class="dot"></i><span data-metric-title>Seitenaufrufe</span></span><span><i class="dot previous"></i>Vorzeitraum</span></div><div class="chart" data-chart></div><div class="chartmeta"><span data-period></span><span>Tageswerte · Europe/Berlin</span></div>'
def metrics():return '<div class="kpis" data-kpis></div>'
def bars(rows):return '<div data-bars=\''+json.dumps(rows)+'\'></div>'
def tableblock():return '<div class="tablebar"><div><h2>Deine Links im Vergleich</h2><p class="dim">Beispielauswahl · Titel anklicken für Details</p></div><label class="search-label">'+icon('Search')+'<input id="search" placeholder="Links durchsuchen" aria-label="Links durchsuchen"></label></div><div class="tablewrap" data-table></div><div class="detail" data-detail-panel hidden></div>'
def metricselect():return '<select id="metric" aria-label="Kennzahl im Diagramm"><option value="views">Seitenaufrufe</option><option value="downloads">Downloadstarts</option><option value="redirects">Weiterleitungen</option></select>'
def toolbar():return '<div class="toolbar"><div class="segmented" aria-label="Zeitraum"><button data-days="7" aria-pressed="false">7 Tage</button><button data-days="28" aria-pressed="true">28 Tage</button></div><button data-export>'+icon('Download')+' CSV</button></div>'
insights='<div class="insight"><span class="dim">Stärkste Freigabe</span><span class="big">Brand Assets 2026</span><p>37,9 % aller Seitenaufrufe entfallen auf dein Brand-Kit.</p></div><div class="insight"><span class="dim">Verhältnis Abschlüsse / Starts</span><span class="big">92,7 % <span class="trend">+1,5 Pp.</span></span><p>Serverereignisse im Zeitraum, keine personenbezogene Conversion.</p></div><div class="insight"><span class="dim">ZIP-Übertragungen · 28-Tage-Beispiel</span><span class="big">684 <span class="dim">von 732 Starts</span></span><p>Archivübertragungen werden getrennt von Einzeldateien gezählt.</p></div>'
sourcebars=bars([['Direkt / unbekannt',64,None],['example.com',22,'--chart-2'],['newsletter.example',9,'--chart-3'],['Andere Ursprünge',5,None]])
devices='<div class="device-layout"><div class="donut" role="img" aria-label="Browser-Beispielverteilung: Chrome 64, Safari 25, Firefox 7, unbekannt 4 Prozent"></div><div>'+bars([['Chrome',64,None],['Safari',25,'--chart-2'],['Firefox',7,'--chart-3'],['Unbekannt',4,None]])+'</div></div>'
activity=''.join('<div class="listrow"><span class="fileicon">'+icon(ic)+'</span><div class="identity"><strong>'+title+'</strong><small>'+sub+'</small></div><span class="dim">'+time+'</span></div>' for ic,title,sub,time in [('CheckCheck','Serverübertragung beendet','/brand-kit · Brand-Guidelines.pdf','14:42'),('Eye','Freigabe aufgerufen','/summer-26 · Safari / iOS','14:41'),('ArrowUpRight','Kurzlink weitergeleitet','/portfolio · Herkunft unbekannt','14:40')])
heading='<div class="heading"><div><div class="overline">Deine Inhalte. Ihre Wirkung.</div><h1>Statistiken</h1><p>Verstehe, was ankommt — und welche Inhalte weiterziehen.</p></div>'+toolbar()+'</div>'
a=heading+metrics()+'<div class="grid">'+panel('Reichweite im Verlauf','Aktueller Zeitraum im Vergleich zu den vorherigen 28 bzw. 7 Tagen',chartblock()+'<div class="note">'+icon('Activity')+'<span><b>Ein klarer Aufwärtstrend.</b> In diesem Beispiel legt die Reichweite um 24,8 % zu.</span></div>',metricselect())+panel('Auf einen Blick','Die wichtigsten Zusammenhänge',insights)+'</div><div class="triple">'+panel('Beliebteste Dateien','Downloadstarts · inklusive fortgesetzter Anfragen','<div data-files></div>')+panel('Woher kommen die Aufrufe?','Referrer-Ursprünge · Konzeptaggregation',sourcebars+'<p class="dim" style="margin-top:20px">Ohne Referrer lässt sich direkte Nutzung nicht sicher unterscheiden.</p>')+panel('Browser-Mix','User-Agent · Konzeptaggregation',devices+'<p class="dim">Angaben des Clients, keine verifizierten Geräte.</p>')+'</div>'+panel('','',''+tableblock())+'<div class="grid">'+panel('Letzte Aktivität','06. November 2026 · Momentaufnahme',activity)+panel('Daten mit Kontext','Was die Zahlen tatsächlich aussagen','<p>Aufrufe sind keine eindeutigen Personen. Ein abgeschlossener Transfer bestätigt keine Speicherung beim Empfänger.</p><details><summary>Messung & Datenumfang</summary><p>Alle Werte sind erfunden. Diagramme sind illustrative Tagesverläufe. Prozentvergleiche und Zusatzanalysen zeigen eine mögliche Erweiterung der heutigen API.</p></details>')+'</div>'
b=heading+'<div class="studio-grid"><aside class="rail"><h3>Analyse-Studio</h3>'+''.join(f'<button data-metric="{key}" aria-pressed="{str(key=="views").lower()}">{icon(ic)}{label}</button>' for key,ic,label in [('views','Eye','Reichweite'),('downloads','Download','Downloads'),('redirects','ArrowUpRight','Kurzlinks')])+'<div class="railnote">DATENGRUNDLAGE<br>Beispieldaten<br><span data-period></span><br>Zeitzone: Europe/Berlin<br><br>Der Kennzahlwechsel wirkt auf den Verlauf. Tabellen zeigen alle Kennzahlen.</div></aside><div>'+metrics()+panel('Verlauf untersuchen','Kennzahl links wechseln · Zeitraum oben auswählen',chartblock(),'<span class="tag">Täglich</span>')+'<div class="grid">'+panel('Wann werden Inhalte abgerufen?','Wochentag × Stunde · festes 28-Tage-Beispiel','<div data-heatmap></div><div class="note">'+icon('Clock')+'<span>Beispielmuster: höhere Aktivität am Nachmittag. Keine Live-Auswertung.</span></div>')+panel('Anfragen nach Browser','Konzeptaggregation · Client-Angaben',bars([['Chrome',64,None],['Safari',25,'--chart-2'],['Firefox',7,'--chart-3'],['Unbekannt',4,None]]))+'</div>'+panel('','',tableblock())+'<div class="grid">'+panel('Dateien im Fokus','Downloadstarts im gewählten Zeitraum','<div data-files></div>')+panel('Ereignisprotokoll','Letzte Beispielereignisse · 06. Nov.',activity)+'</div></div></div>'
c='<div class="heading"><div class="overline">Statistiken / Dein Überblick</div>'+toolbar()+'</div><div class="report-intro"><div><span class="tag" data-period></span><h1>Deine Inhalte finden<br>immer mehr Anklang.</h1><p>Mehr Aufrufe, mehr Downloads, mehr Bewegung. Dein Brand-Kit führt die Liste an und prägt diesen Zeitraum.</p><span class="dim">Redaktioneller Beispielreport · keine automatisch erstellte Analyse</span></div><div class="hero-number"><span class="dim">Seitenaufrufe insgesamt</span><strong data-total>12.844</strong><span class="trend">↗ 24,8 % gegenüber dem Vorzeitraum</span><span class="dim">Wiederholte Aufrufe eingeschlossen</span></div></div><div class="chapter"><div class="chapter-title"><div class="num">01 / ENTWICKLUNG</div><h2>Die Richtung<br>stimmt.</h2><p>Aufrufe und Übertragungen im Zusammenhang betrachten.</p></div><div>'+metrics()+chartblock()+'</div></div><div class="chapter"><div class="chapter-title"><div class="num">02 / INHALTE</div><h2>Was besonders<br>gut ankommt.</h2><p>Die Inhalte mit den meisten Downloadanfragen.</p></div><div class="grid">'+panel('Dateien mit Wirkung','Downloadstarts · inklusive Range-Anfragen','<div data-files></div>')+'<div><div class="overline">Im Fokus</div><div class="callout"><strong>Mehr als jeder dritte Aufruf gilt deinem Brand-Kit.</strong><p>4.862 von 12.844 Aufrufen im 28-Tage-Beispiel. Die neue Gestaltung macht solche Zusammenhänge sofort sichtbar.</p></div><div class="note">'+icon('Info')+'<span>Die Ursache des Anstiegs lässt sich aus Ereigniszahlen allein nicht ableiten.</span></div></div></div></div><div class="chapter"><div class="chapter-title"><div class="num">03 / KONTEXT</div><h2>Ein Blick<br>hinter die Zahlen.</h2><p>Herkunft und Browser als zusätzliche Perspektiven.</p></div><div class="grid">'+panel('Herkunft der Aufrufe','Konzeptaggregation · Referrer-Ursprünge',sourcebars)+panel('Browser-Mix','Konzeptaggregation · ungeprüfter User-Agent',devices)+'</div></div><div class="chapter"><div class="chapter-title"><div class="num">04 / DETAILS</div><h2>Alles im<br>Vergleich.</h2><p>Einzelne Links öffnen, durchsuchen und Beispielwerte exportieren.</p></div><div>'+tableblock()+'</div></div>'
variants=[('01-insights.html','Insights-Dashboard','dashboard',a),('02-studio.html','Analyse-Studio','studio',b),('03-report.html','Statistik-Report','report',c)]
for filename,title,kind,content in variants:
    nav=''.join(f'<a class="{"current" if f==filename else ""}" href="{f}"'+(' aria-current="page"' if f==filename else '')+f'>{i+1:02d} {t}</a>' for i,(f,t,_,_) in enumerate(variants))
    shell=f'<div class="wrap {kind}"><header class="app-header"><div class="brand"><img src="data:image/svg+xml;base64,{logo}" alt="">ShareLyze</div><nav class="header-nav" aria-label="App-Navigation als Designvorschau">'+''.join(f'<span title="{label}" aria-label="{label}" class="{active}">{icon(ic)}</span>' for ic,label,active in [('FolderOpen','Freigaben',''),('Link','Kurzlinks',''),('ChartNoAxesCombined','Statistiken','active'),('Settings','Einstellungen','')])+f'</nav><div class="account"><button class="iconbutton" data-theme-toggle aria-label="Hellmodus aktivieren">{icon("Sun")}</button><span class="avatar">FE</span></div></header><nav class="conceptbar" aria-label="Entwürfe">{nav}<span class="demo">Konzept · Beispieldaten</span></nav><main>{content}</main><footer class="footer"><span>ShareLyze · Statistik-Konzept · 06. November 2026<br>Alle Werte sind fiktiv. Keine eindeutigen Besucher oder bestätigten Dateispeicherungen.</span><span>Zeitraum, Kennzahl, Suche, Details, CSV und Theme: lokale Demo.<br>Zusätzliche Aggregationen benötigen eine API-Erweiterung.</span></footer></div>'
    doc=f'<!doctype html><html lang="de" data-theme="dark"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ShareLyze · {title}</title><style>/* Existing ShareLyze stylesheet, embedded for standalone use. */\n{base}\n/* Scoped concept overrides. */\n{css}</style></head><body>{shell}<script>{js.replace("ICONS",json.dumps(icons)).replace("VARIANT",json.dumps(kind))}</script></body></html>'
    if kind == 'dashboard':
        doc=doc.replace('</head>', '<style>'+ (OUT/'insights-interactive.css').read_text() +'</style></head>')
        doc=doc.replace('</body>', '<script>'+ (OUT/'insights-interactive.js').read_text() +'</script></body>')
    (OUT/filename).write_text(doc)
print('Generated three self-contained HTML designs.')
